  bool DualAllowed{get{return Ready&&HasWeapon&&!holstered&&!presentationSuppressed&&!gameplayPaused&&hadFocus&&isActiveAndEnabled&&Health>0;}}
  IEnumerator LoadDualPresentation(){for(int n=0;n<2;n++){string profile=n==0?"uzis":"matadors";int index=Array.IndexOf(weaponIds,profile);float scale=modelScales[index];for(int side=0;side<2;side++){var node=new GameObject("Source canonical paired "+profile+" "+side).transform;node.SetParent(weaponModels[index],false);node.localPosition=new Vector3(side==0?.09f:-.09f,0,0)/scale;node.localRotation=Quaternion.Euler(0,(side==0?.12f:-.12f)*Mathf.Rad2Deg,0);yield return visuals.Load("dual-"+profile,node);}var host=new GameObject("Actual two-hand "+profile+" presentation");host.transform.SetParent(content,false);var presenter=host.AddComponent<R24DualPresentation>();dualViews[n]=presenter;presenter.Initialize(profile,head,player,left,right,content);presenter.SetMotionDamping(motionDamping);presenter.HapticRequested=Pulse;presenter.GlobalHeadObstructed=delegate{return MeleeWorldInputAllowed!=null&&!MeleeWorldInputAllowed();};presenter.LocomotionAnchor=delegate{return DualLocomotionAnchor==null?player.position:DualLocomotionAnchor();};presenter.HeadPathClear=delegate(int hand){var tracked=hand==0?left:right;Vector3 d=tracked.position-head.transform.position;RaycastHit hit;return d.sqrMagnitude<.000001f||!Nearest(head.transform.position,d.normalized,d.magnitude,out hit);};while(!presenter.Ready){if(presenter.Failure!=null)throw new InvalidOperationException(presenter.Failure);yield return null;}presenter.View.SetSfxVolume(sfxVolume);presenter.View.TraceAim=DualAim;presenter.Suspend();}
  }
  Vector3 DualAim(Vector3 origin,Vector3 direction,float range){RaycastHit hit;Vector3 segment=origin-head.transform.position;if(segment.sqrMagnitude>1e-6f&&Nearest(head.transform.position,segment.normalized,segment.magnitude,out hit))return hit.point;return RemoteAimPoint(origin,direction,Nearest(origin,direction,range,out hit)?hit.point:origin+direction*range);}
