  void RecordDualShot(R24DualVolley shot){var rays=new Float3[shot.PelletCount];for(int i=0;i<rays.Length;i++)rays[i]=shot.Direction(i);LaunchBullets(shot.Pose.Origin,rays,.045f,shot.Side);lastAcceptedShot=shot.Pose;lastAcceptedPoseValid=true;LastAcceptedShotActionId=activeActionId;LastAcceptedNativeShot=round.Dual.TotalShots;}
